<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#242424;font-size:11px}h1{font-size:24px;margin:0}h2{font-size:16px;margin-top:30px}.muted{color:#777}.rule{border-top:2px solid #b99a5b;margin:16px 0 24px}.meta{width:100%;border-collapse:collapse}.meta td{padding:9px;border-bottom:1px solid #e7e2d8}.meta td:first-child{width:27%;font-weight:bold;color:#555}.qr{width:120px}.footer{position:fixed;bottom:12px;left:0;right:0;color:#777;font-size:9px;text-align:center}</style></head><body><h1>GEMLAB DESK</h1><p class="muted">GEMSTONE LABORATORY · SAMPLE IDENTIFICATION REPORT</p><div class="rule"></div><h2>REPORT {{ $r->report_no }}</h2><table class="meta"><tr><td>Customer</td><td>{{ $c->name }}</td></tr><tr><td>Company</td><td>{{ $c->company ?: '—' }}</td></tr><tr><td>Order number</td><td>{{ $o->order_no }}</td></tr><tr><td>Sample number</td><td>{{ $s->sample_no }}</td></tr><tr><td>Description</td><td>{{ $s->description }}</td></tr><tr><td>Gemstone type</td><td>{{ $s->gemstone_type ?: 'Not determined' }}</td></tr><tr><td>Colour</td><td>{{ $s->colour ?: 'Not recorded' }}</td></tr><tr><td>Weight (ct)</td><td>{{ $s->weight ?: '—' }}</td></tr><tr><td>Conclusion</td><td>{{ $r->conclusion }}</td></tr><tr><td>Treatment</td><td>{{ $r->treatment }}</td></tr><tr><td>Origin</td><td>{{ $r->origin }}</td></tr><tr><td>Issued at</td><td>{{ $r->issued_at }}</td></tr><tr><td>Approved by</td><td>{{ $r->approved_by }}</td></tr></table><table style="width:100%;margin-top:25px"><tr><td><p>Verify this report:</p><small>{{ $verifyUrl }}</small></td><td style="text-align:right"><img class="qr" src="{{ $qrData }}"></td></tr></table><div class="footer">DEMONSTRATION SOFTWARE OUTPUT — NOT AN OFFICIAL GTL / IIGJ CERTIFICATE</div></body></html>
